import {
  COUNTRY_GLOBAL_KEY,
  COUNTRY_GLOBAL_LABEL,
  FilterForm,
  Option,
} from 'models/Filters';
import { COMMERCIAL_RESULTS_PAGE_NAME } from 'pages/pillars/ValueCreation/CommercialResults/constants';
import { WATCH_TOWER_PAGE_NAME } from 'pages/pillars/ValueCreation/WatchTower/constants';

export type FilterSelectClearableScope = 'commercial' | 'all';

/**
 * `'commercial'` — clear (x) only on Commercial Results drawer selects.
 * `'all'` — same behaviour on every page that wires these field keys (align with design / PM).
 */
export const FILTER_SELECT_CLEARABLE_SCOPE: FilterSelectClearableScope =
  'commercial';

const COMMERCIAL_CLEARABLE_FIELD_KEYS = new Set([
  'country',
  'region',
  'brands',
  'sub_brands',
  'sku',
  'channel',
  'pack_type',
  'category',
  'non_alcoholic',
  'growth_levers',
  'beer_price_segment',
  'portfolios',
]);

const WATCH_TOWER_CLEARABLE_FIELD_KEYS = new Set([
  'region',
  'watch_tower_brand',
  'channel',
  'driver',
  'vehicle_level_1',
  'vehicle_level_2',
  'vehicle_level_3',
  'vehicle_level_4',
  'vehicle_level_5',
]);

/** Baseline is null/empty (no “All” row in the preset list). */
const NULLABLE_CLEAR_BASELINE_FIELD_KEYS = new Set(['sub_brands', 'sku']);

export function isNullableClearBaselineFieldKey(fieldKey: string): boolean {
  return NULLABLE_CLEAR_BASELINE_FIELD_KEYS.has(fieldKey);
}

export function isFilterSelectClearableEnabledForPage(
  pageName: string,
): boolean {
  if (FILTER_SELECT_CLEARABLE_SCOPE === 'all') {
    return true;
  }
  return (
    pageName === COMMERCIAL_RESULTS_PAGE_NAME ||
    pageName === WATCH_TOWER_PAGE_NAME
  );
}

export function isClearableFilterFieldKey(fieldKey: string): boolean {
  return (
    COMMERCIAL_CLEARABLE_FIELD_KEYS.has(fieldKey) ||
    WATCH_TOWER_CLEARABLE_FIELD_KEYS.has(fieldKey)
  );
}

function isClearableFilterFieldForPage(
  pageName: string,
  fieldKey: string,
): boolean {
  if (pageName === WATCH_TOWER_PAGE_NAME) {
    return WATCH_TOWER_CLEARABLE_FIELD_KEYS.has(fieldKey);
  }
  if (pageName === COMMERCIAL_RESULTS_PAGE_NAME) {
    return COMMERCIAL_CLEARABLE_FIELD_KEYS.has(fieldKey);
  }
  return (
    FILTER_SELECT_CLEARABLE_SCOPE === 'all' &&
    isClearableFilterFieldKey(fieldKey)
  );
}

function isNullableClearBaselineForPage(
  pageName: string | undefined,
  fieldKey: string,
): boolean {
  return (
    (pageName === WATCH_TOWER_PAGE_NAME &&
      WATCH_TOWER_CLEARABLE_FIELD_KEYS.has(fieldKey)) ||
    isNullableClearBaselineFieldKey(fieldKey)
  );
}

/**
 * Option that represents the “no narrow filter” / baseline choice (e.g. All, ABI/All countries).
 * When the list includes **All**, that wins before `defaults[fieldKey]` — Redux defaults for
 * `brands` (and similar flat lists) may still be the first SKU from the registry, not “All”.
 */
export function findFilterClearSentinelOption(
  fieldKey: string,
  options: Option[],
  defaults?: FilterForm,
): Option | undefined {
  if (!options?.length) {
    return undefined;
  }

  const allLiteral = options.find(
    (o) => o?.value === 'All' || String(o?.value).toUpperCase() === 'ALL',
  );
  if (allLiteral) {
    return allLiteral;
  }

  const defaultKey = defaults?.[fieldKey];
  if (defaultKey != null && defaultKey !== '') {
    const match = options.find((o) => String(o.value) === String(defaultKey));
    if (match) {
      return match;
    }
  }

  if (fieldKey === 'country') {
    return options.find(
      (o) =>
        o?.value === COUNTRY_GLOBAL_KEY ||
        o?.value === 'ABI' ||
        String(o?.label) === COUNTRY_GLOBAL_LABEL,
    );
  }

  const allRegions = options.find((o) =>
    String(o?.label ?? '')
      .toLowerCase()
      .includes('all region'),
  );
  if (allRegions) {
    return allRegions;
  }

  return undefined;
}

export function resolveFilterClearTargetOption(
  fieldKey: string,
  options: Option[],
  defaults?: FilterForm,
  pageName?: string,
): Option | undefined {
  if (isNullableClearBaselineForPage(pageName, fieldKey)) {
    return { value: null, label: '' };
  }
  return findFilterClearSentinelOption(fieldKey, options, defaults);
}

export function shouldShowFilterSelectClearIndicator(
  pageName: string,
  fieldKey: string,
  currentValue: string | null | undefined,
  options: Option[],
  defaults?: FilterForm,
): boolean {
  if (!isFilterSelectClearableEnabledForPage(pageName)) {
    return false;
  }
  if (!isClearableFilterFieldForPage(pageName, fieldKey)) {
    return false;
  }

  if (isNullableClearBaselineForPage(pageName, fieldKey)) {
    const v = currentValue ?? '';
    if (v === '') return false;
    return String(v).toLowerCase() !== 'all';
  }

  const sentinel = findFilterClearSentinelOption(fieldKey, options, defaults);
  if (sentinel?.value == null || sentinel.value === '') {
    return false;
  }

  const v = currentValue ?? '';
  return String(v) !== String(sentinel.value);
}
